home.css:
.wrap{max-width:1240px;margin:0 auto;padding:0 40px}
/* hero */
.hero{background:var(--g0);color:#fff;padding:150px 0 0;position:relative;overflow:hidden}
.hero:before{content:"";position:absolute;inset:0;background:repeating-linear-gradient(90deg,transparent 0 calc(25% - 1px),var(--hl) calc(25% - 1px) 25%);opacity:.45;pointer-events:none;max-width:1240px;margin:0 auto}
.hero .wrap{position:relative}
.eyebrow{font-size:14px;color:var(--ch);margin-bottom:20px;display:flex;align-items:center;gap:14px}
.eyebrow:before{content:"";width:40px;height:1px;background:var(--ch)}
.hero h1{font:300 clamp(42px,6.3vw,96px)/1.02 var(--f);letter-spacing:-.04em;max-width:1000px}
.hero h1 em{color:var(--ch)}
.hero h1 .l{display:block;overflow:hidden;padding-bottom:.12em;margin-bottom:-.12em}
.hero h1 .l>span{display:block;animation:up 1s var(--ease) both}
.hero h1 .l:nth-child(2)>span{animation-delay:.12s}
@keyframes up{from{transform:translateY(110%)}to{transform:none}}
.hero .sub{display:flex;gap:48px;align-items:flex-end;justify-content:space-between;margin:30px 0 0;flex-wrap:wrap;animation:fade 1s var(--ease) .5s both}
.hero .sub p{font-size:20px;color:#b9bec8;max-width:520px;line-height:1.55}
.hero .acts{display:flex;gap:14px;align-items:center;flex-wrap:wrap}
@keyframes fade{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
/* console */
.con{margin-top:56px;background:var(--g1);border:1px solid var(--hl2);border-bottom:0;border-radius:14px 14px 0 0;animation:fade 1.1s var(--ease) .8s both;position:relative}
.con .top{display:flex;align-items:center;gap:14px;padding:16px 22px;border-bottom:1px solid var(--hl);font-size:14px;color:var(--mutd)}
.con .top b{color:#fff;font-weight:500}.con .top .r{margin-left:auto;display:flex;align-items:center;gap:8px}
.dot{width:7px;height:7px;border-radius:50%;background:var(--ok);animation:pl 2.4s ease-in-out infinite}
@keyframes pl{50%{opacity:.3}}
.cg{display:grid;grid-template-columns:230px 1fr 310px}
.cg>div{padding:22px}
.cg>div+div{border-left:1px solid var(--hl)}
.k{padding:0 0 18px;margin-bottom:18px;border-bottom:1px solid var(--hl)}
.k:last-child{border:0;margin:0}
.k span{font-size:13px;color:var(--mutd)}
.k b{display:block;font:300 40px/1.15 var(--f);letter-spacing:-.02em;font-variant-numeric:tabular-nums;margin-top:2px}
.k small{font-size:12.5px;color:var(--mutd)}
.k svg{display:block;width:100%;height:30px;margin-top:8px}
.k path{fill:none;stroke:var(--ch);stroke-width:1.5;stroke-dasharray:400;stroke-dashoffset:400;animation:dr 2.2s var(--ease) 1.4s forwards}
@keyframes dr{to{stroke-dashoffset:0}}
.gt{position:relative}
.gh{display:grid;grid-template-columns:90px repeat(11,1fr);font-size:12px;color:var(--mutd);margin-bottom:8px}
.gr{display:grid;grid-template-columns:90px 1fr;align-items:center;height:50px;border-top:1px solid var(--hl)}
.gr>span{font-size:14px;color:#d9dce2}
.tr{position:relative;height:100%;background:repeating-linear-gradient(90deg,transparent 0 calc(100%/11 - 1px),var(--hl) calc(100%/11 - 1px) calc(100%/11))}
.bar{position:absolute;top:11px;height:28px;border-radius:3px;font-size:12px;line-height:28px;padding:0 9px;white-space:nowrap;overflow:hidden;transform-origin:left;animation:grow .9s var(--ease) both}
.bar.d{background:#2a2f38;color:#9aa0ab}
.bar.a{background:var(--ch);color:var(--g0);font-weight:500}
.bar.p{border:1px dashed var(--hl2);color:#aab0bb}
@keyframes grow{from{transform:scaleX(0);opacity:0}to{transform:none;opacity:1}}
.now{position:absolute;top:34px;bottom:0;width:1px;background:var(--ex);left:var(--x);animation:mv 40s linear infinite}
.now:before{content:"";position:absolute;top:-4px;left:-3px;width:7px;height:7px;border-radius:50%;background:var(--ex)}
@keyframes mv{from{left:calc(90px + (100% - 90px) * .40)}to{left:calc(90px + (100% - 90px) * .56)}}
.fd h4{font:500 13px var(--f);color:var(--mutd);margin-bottom:12px}
.ev{display:grid;grid-template-columns:48px 1fr;gap:10px;padding:11px 0;border-top:1px solid var(--hl);font-size:14px;line-height:1.4;animation:evin .6s var(--ease) both}
.ev time{color:var(--mutd);font-variant-numeric:tabular-nums}
.ev b{font-weight:500;color:#fff}
.ev i{font-style:normal;color:var(--ch)}
@keyframes evin{from{opacity:0;transform:translateY(-10px)}to{opacity:1;transform:none}}
.fd{min-height:330px;overflow:hidden}
/* light sections */
section{padding-top:96px}
.kick{font-size:14px;color:var(--chd);margin-bottom:16px;display:flex;align-items:center;gap:14px}
.kick:before{content:"";width:40px;height:1px;background:var(--chd)}
h2{font:300 clamp(40px,5.4vw,78px)/1.04 var(--f);letter-spacing:-.035em;max-width:900px}
h2 em{color:var(--chd)}
.two{display:grid;grid-template-columns:5fr 7fr;gap:64px;margin-top:44px;align-items:start}
.two p.l{font-size:19px;line-height:1.5;color:#41444b;max-width:420px}
.dl{border-top:1px solid var(--ink)}
.dl>div{display:grid;grid-template-columns:170px 1fr;gap:24px;padding:18px 0;border-bottom:1px solid #cfc9ba}
.dl dt{font:500 15px var(--f);color:var(--chd);padding-top:3px}
.dl dd{font-size:18px;line-height:1.55;color:#2a2d33}
.dl dd span{white-space:nowrap}.dl dd span:not(:last-child):after{content:"";display:inline-block;width:4px;height:4px;border-radius:50%;background:#b7ad92;margin:0 14px 3px}
/* dark security */
.dk{background:var(--g0);color:#fff;margin-top:96px;padding:96px 0}
.dk h2{color:#fff;max-width:760px}.dk h2 em{color:var(--ch)}.dk .kick{color:var(--ch)}.dk .kick:before{background:var(--ch)}
.sec{display:grid;grid-template-columns:1fr 1fr;gap:0 64px;margin-top:44px}
.sec>div{display:grid;grid-template-columns:44px 1fr;gap:6px;padding:20px 0;border-top:1px solid var(--hl2)}
.sec .n{font:italic 400 22px var(--s);color:var(--ch)}
.sec h3{font:500 20px var(--f);margin-bottom:4px}.sec p{color:#aeb3bd;font-size:16px;line-height:1.5}
/* sectors */
.sx{margin-top:40px;border-top:1px solid var(--ink)}
.sx a{display:grid;grid-template-columns:60px 1fr 1.2fr 40px;gap:20px;align-items:center;padding:20px 0;border-bottom:1px solid #cfc9ba;position:relative;transition:padding-left .4s var(--ease)}
.sx a:before{content:"";position:absolute;left:0;bottom:-1px;height:1px;width:0;background:var(--chd);transition:width .5s var(--ease)}
.sx a:hover{padding-left:20px}.sx a:hover:before{width:100%}
.sx .n{font:italic 400 20px var(--s);color:var(--chd)}
.sx h3{font:300 clamp(32px,3.8vw,54px)/1.05 var(--f);letter-spacing:-.03em}
.sx p{color:var(--mut);font-size:16.5px}
.sx svg{width:22px;height:22px;transition:transform .35s var(--ease);justify-self:end}.sx a:hover svg{transform:translateX(6px)}
/* process */
.pr{display:grid;grid-template-columns:repeat(3,1fr);gap:40px;margin-top:44px;position:relative}
.pr:before{content:"";position:absolute;left:0;top:0;height:1px;width:100%;background:var(--ink);transform-origin:left;transform:scaleX(0);transition:transform 1.4s var(--ease)}
.pr.in:before{transform:scaleX(1)}
.pr>div{padding-top:22px}
.pr b{font:italic 400 64px/1 var(--s);color:var(--chd);display:block;margin-bottom:14px}
.pr h3{font:400 28px var(--f);letter-spacing:-.02em;margin-bottom:8px}
.pr p{color:#50535a;max-width:320px}
/* cta */
.cta{background:var(--g0);color:#fff;margin-top:96px;padding:96px 0 84px}
.cta h2{color:#fff;max-width:900px}.cta h2 em{color:var(--ch)}
.cta .row{display:flex;gap:30px;align-items:center;margin-top:50px;flex-wrap:wrap}
.cta .tel{font:300 clamp(30px,3.6vw,48px) var(--f);letter-spacing:-.02em;font-variant-numeric:tabular-nums}
/* reveal */
@media(max-width:1060px){.cg{grid-template-columns:1fr}.cg>div+div{border-left:0;border-top:1px solid var(--hl)}.two{grid-template-columns:1fr;gap:40px}.sec{grid-template-columns:1fr}.pr{grid-template-columns:1fr}.sx a{grid-template-columns:40px 1fr 30px}.sx p{grid-column:2/3;grid-row:2}.dl>div{grid-template-columns:1fr;gap:8px}.gh,.gr{grid-template-columns:70px 1fr}.gh{display:none}.k b{font-size:32px}}
@media(max-width:600px){.wrap{padding:0 22px}.hero{padding-top:140px}section{padding-top:100px}}
@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}.js .rv{opacity:1!important;transform:none!important}.k path{stroke-dashoffset:0!important}.pr:before{transform:none!important}}

.pkt{display:flex;margin-top:40px;border-bottom:1px solid var(--ink);gap:28px;flex-wrap:wrap}
.pkt button{background:none;border:0;border-bottom:3px solid transparent;margin-bottom:-1px;padding:0 0 14px;cursor:pointer;text-align:left;font:inherit;color:var(--mut);transition:border-color .3s var(--ease),color .3s}
.pkt button b{display:block;font:400 26px/1.2 var(--f);letter-spacing:-.02em;color:var(--ink)}
.pkt button span{font-size:14px}
.pkt button:hover{color:var(--ink)}
.pkt button[aria-selected=true]{border-bottom-color:var(--chd);color:var(--ink)}
.pkp{display:grid;grid-template-columns:4fr 8fr;gap:56px;padding-top:32px}
.pkp[hidden]{display:none}
.pkp .sum{position:sticky;top:24px;align-self:start}
.pkp .sum h3{font:300 36px/1.1 var(--f);letter-spacing:-.03em}
.pkp .price{font:300 54px/1.1 var(--f);letter-spacing:-.04em;margin:10px 0 12px;font-variant-numeric:tabular-nums}
.pkp .price small{font:400 14px var(--f);letter-spacing:0;color:var(--mut);margin-left:6px}
.pkp .sum p{color:#41444b;margin-bottom:12px;font-size:17px;line-height:1.5}
.pkp .inc{font-weight:500;color:var(--chd)!important}
.mod{display:grid;grid-template-columns:1fr 1.25fr;gap:28px;padding:20px 0;border-top:1px solid #cfc9ba}
.mod:first-child{border-top:1px solid var(--ink)}
.mod h4{font:500 20px/1.25 var(--f);margin-bottom:6px}
.mod p{color:var(--mut);font-size:15.5px;line-height:1.5}
.mod ul{list-style:none;padding:0}
.mod li{position:relative;padding:5px 0 5px 20px;font-size:15.5px;line-height:1.45;border-top:1px solid rgba(20,22,26,.07)}
.mod li:first-child{border:0;padding-top:0}
.mod li:before{content:"";position:absolute;left:0;top:13px;width:9px;height:1px;background:var(--chd)}
.mod li:first-child:before{top:8px}
.ev2{margin-top:56px}.ev2 h3,.mxw h3{font:300 30px var(--f);letter-spacing:-.03em;margin-bottom:16px}
.evg{display:grid;grid-template-columns:repeat(3,1fr);gap:0 40px;border-top:1px solid var(--ink)}
.evg div{padding:16px 0;border-bottom:1px solid #cfc9ba}
.evg h4{font:500 16px var(--f)}.evg p{color:var(--mut);font-size:15px;line-height:1.45}
.mxw{margin-top:56px;overflow-x:auto}
.mx{width:100%;border-collapse:collapse;min-width:640px;font-size:15.5px}
.mx th,.mx td{padding:10px 14px;text-align:center;border-bottom:1px solid #d6d0c2}
.mx th:first-child,.mx td:first-child{text-align:left;padding-left:0}
.mx thead th{font:500 14px var(--f);color:var(--chd);border-bottom:1px solid var(--ink);position:sticky;top:0;background:var(--iv)}
.mx tr.g th{text-align:left;font:500 13px var(--f);color:var(--chd);padding:18px 0 8px;border-bottom:1px solid var(--ink)}
.mx td.y{color:var(--chd);font-weight:600}.mx td.n{color:#b5ad98}
.rm{margin-top:36px;border-top:1px solid var(--ink)}
.rm>div{display:grid;grid-template-columns:140px 1fr 1.3fr;gap:24px;align-items:baseline;padding:18px 0;border-bottom:1px solid #cfc9ba}
.st{font:500 13px var(--f);color:var(--chd);border:1px solid var(--chd);padding:3px 10px;width:max-content}
.rm h3{font:300 28px/1.15 var(--f);letter-spacing:-.025em}.rm p{color:var(--mut);font-size:16px;line-height:1.5}
@media(max-width:1060px){.pkp{grid-template-columns:1fr;gap:20px}.pkp .sum{position:static}.mod{grid-template-columns:1fr;gap:10px}.evg{grid-template-columns:1fr 1fr}.rm>div{grid-template-columns:1fr;gap:6px}}
@media(max-width:600px){.evg{grid-template-columns:1fr}.pkt{gap:16px}.pkt button b{font-size:20px}}
.pcs{display:grid;grid-template-columns:repeat(4,1fr);margin-top:44px;border-top:1px solid var(--ink)}
.pc{position:relative;padding:28px 26px 30px;border-right:1px solid #cfc9ba;border-bottom:1px solid #cfc9ba;display:flex;flex-direction:column}
.pc:first-child{border-left:1px solid #cfc9ba}
.pc.hot{background:var(--g0);color:#fff;border-color:var(--g0);margin-top:-1px;padding-top:29px}
.pc .tag{position:absolute;top:-1px;left:26px;transform:translateY(-100%);font:500 12.5px var(--f);background:var(--chd);color:#fff;padding:4px 10px}
.pc h3{font:400 26px/1.15 var(--f);letter-spacing:-.02em}
.pc .price{font:300 46px/1.1 var(--f);letter-spacing:-.04em;margin:12px 0 10px;font-variant-numeric:tabular-nums}
.pc .price small{display:block;font:400 13.5px var(--f);letter-spacing:0;color:var(--mut);margin-top:2px}
.pc.hot .price small{color:var(--mutd)}
.pc p{color:#50535a;font-size:15.5px;line-height:1.5;min-height:70px}
.pc.hot p{color:#b4b9c3}
.pc ul{list-style:none;padding:0;margin:14px 0 26px;flex:1}
.pc li{position:relative;padding:9px 0 9px 20px;font-size:15.5px;line-height:1.4;border-top:1px solid rgba(20,22,26,.1)}
.pc.hot li{border-color:var(--hl2)}
.pc li:before{content:"";position:absolute;left:0;top:19px;width:9px;height:1px;background:var(--chd)}
.pc.hot li:before{background:var(--ch)}
.pc .btn{width:100%}
.pc .btn.o{color:var(--chd);border-color:var(--chd)}.pc .btn.o:hover{background:var(--chd);color:#fff}
.pkdet{margin-top:28px;border-bottom:1px solid #cfc9ba}
.pkdet summary{list-style:none;cursor:pointer;display:flex;justify-content:space-between;align-items:center;padding:18px 0;font:400 20px var(--f);letter-spacing:-.01em;min-height:56px}
.pkdet summary::-webkit-details-marker{display:none}
.pkdet summary i{width:14px;height:14px;position:relative;flex:none}
.pkdet summary i:before,.pkdet summary i:after{content:"";position:absolute;left:0;right:0;top:6px;height:1px;background:var(--ink);transition:transform .3s var(--ease)}
.pkdet summary i:after{transform:rotate(90deg)}
.pkdet[open] summary i:after{transform:none}
.pkdet .pkt{margin-top:8px}
.lk{display:flex;gap:32px;flex-wrap:wrap;margin-top:28px}
.lnk{display:inline-flex;align-items:center;gap:10px;font:500 16px var(--f);color:var(--chd);border-bottom:1px solid var(--chd);padding:6px 0}
.lnk svg{width:16px;height:16px;transition:transform .25s var(--ease)}.lnk:hover svg{transform:translateX(4px)}
#usta .lnk{margin-top:30px}
.faq{margin-top:36px;border-top:1px solid var(--ink);max-width:880px}
.faq details{border-bottom:1px solid #cfc9ba}
.faq summary{list-style:none;cursor:pointer;display:flex;justify-content:space-between;gap:20px;padding:20px 0;font:300 24px/1.25 var(--f);letter-spacing:-.02em;min-height:60px}
.faq summary::-webkit-details-marker{display:none}
.faq summary:after{content:"+";font:300 28px/1 var(--f);color:var(--chd);transition:transform .3s var(--ease)}
.faq details[open] summary:after{transform:rotate(45deg)}
.faq p{padding:0 40px 22px 0;color:#41444b;font-size:17.5px;max-width:700px}
.cta .cg2{display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:center}
.cta .cl{color:#aeb3bd;font-size:19px;margin-top:20px;max-width:440px}
.cta .tel{display:block;margin-top:34px}
.cta .frm{background:var(--g1);border:1px solid var(--hl2);padding:28px;display:grid;grid-template-columns:1fr 1fr;gap:16px}
.cta .frm label{display:block;font:500 13.5px var(--f);color:var(--mutd);margin-bottom:6px}
.cta .frm input,.cta .frm select{width:100%;min-height:50px;background:var(--g0);border:1px solid var(--hl2);color:#fff;font:400 16px var(--f);padding:0 14px;border-radius:0}
.cta .frm input:focus,.cta .frm select:focus{outline:2px solid var(--ch);outline-offset:0}
.cta .frm .bt{grid-column:1/-1;display:flex;align-items:center;justify-content:center;min-height:54px;background:var(--ch);color:var(--g0);font:500 16px var(--f);border:1px solid var(--ch);transition:background-color .25s,color .25s}
.cta .frm .bt:hover{background:transparent;color:var(--ch)}
.cta .frm small{grid-column:1/-1;color:var(--mutd);font-size:13px}
#kayit{scroll-margin-top:0}
.vb{display:none}
@media(max-width:1100px){.pcs{grid-template-columns:1fr 1fr}.pc:nth-child(odd){border-left:1px solid #cfc9ba}.pc.hot{margin-top:0}.pc .tag{position:static;transform:none;display:inline-block;margin-bottom:12px}.cta .cg2{grid-template-columns:1fr;gap:44px}}
@media(max-width:700px){
.wrap{padding:0 20px}
.hero{padding-top:104px}
.hero .sub{margin-top:22px;gap:26px}.hero .sub p{font-size:17.5px}
.hero .acts{width:100%}.hero .acts .btn{flex:1 1 100%}
.con{margin-top:40px}
section{padding-top:64px}
h2{font-size:clamp(34px,10vw,48px)}
.pcs{grid-template-columns:1fr}.pc{border-left:1px solid #cfc9ba;padding:24px 20px}.pc p{min-height:0}
.dk,.cta{padding:64px 0;margin-top:64px}
.cta .frm{grid-template-columns:1fr;padding:20px}
.faq summary{font-size:20px}
.sx a{padding:18px 0}.sx h3{font-size:30px}
.mx{font-size:14px}
}
@media(max-width:700px){.dl dd span:not(:last-child):after{display:none}.dl dd span{margin-right:16px;display:inline-block}}

