inner.mobil-yeni-ic1.css:
.vb{display:none}
.burger{color:var(--ink,#161a21)}
.mnu{display:none}
@media(max-width:900px){
body{padding-bottom:calc(84px + env(safe-area-inset-bottom))!important}
.vb{position:fixed;z-index:90;left:0;right:0;bottom:0;display:grid;grid-template-columns:1.22fr 1fr;gap:10px;padding:12px 12px calc(12px + env(safe-area-inset-bottom));background:#fff;border-top:1px solid #e2dccd;box-shadow:none}
.vb a{height:54px;border-radius:3px;display:flex;align-items:center;justify-content:center;gap:7px;color:#fff;font-weight:700;font-size:14px;letter-spacing:-.1px;white-space:nowrap;text-decoration:none}
.vb .p1{background:linear-gradient(100deg,#161a21,#161a21);box-shadow:none}
.vb .p2{background:linear-gradient(100deg,#3e6250,#6f9682);box-shadow:none}
