.mn-l a b{font:700 12px ui-monospace,Menlo,Consolas,monospace;color:#8a6d2f;width:22px}
.mn-l a span{flex:1;font-weight:800;font-size:18px;line-height:1.15;letter-spacing:-.3px;display:flex;flex-direction:column;gap:1px}
.mn-l a small{font-weight:500;font-size:12.5px;line-height:1.2;color:#40444c;letter-spacing:0}
.mn-l a svg{opacity:.6}
.mn-f{display:grid;grid-template-columns:1fr 1.3fr;gap:10px;padding:14px 20px;border-top:1.5px solid #161a21;background:#f5eee0}
.mn-f a{height:50px;border-radius:3px;display:grid;place-items:center;font-weight:800;font-size:15.5px;text-decoration:none}
