/* sprite ikon çipleri */
.o7in .sek,.o7in .sekw a{background:#fbf9f4;border:1px solid #d6d0c2;border-radius:0;box-shadow:none}
.o7in .sek:hover,.o7in .sekw a:hover{border-color:var(--chd)}
/* alt çubuk (mobil) */
.vb{display:none}
.o7in .vb{display:none}
/* reveal bölümler */
.o7in .rv{will-change:auto}
@media(max-width:1100px){.o7in .w{padding:0 28px}}
@media(max-width:700px){
.o7in .w{padding:0 20px}
