}

.o7in .sq,.o7in .dkk{background:var(--g0)!important;color:#fff}
.o7in .sq h2,.o7in .sq h3,.o7in .sq b,.o7in .dkk h2,.o7in .dkk h3,.o7in .cta2 h2,.o7in .cta2 h3,.o7in .pgh h2{color:#fff!important}
