.ib.g{background:linear-gradient(135deg,#3e6250,#6f9682)}.ib.p{background:linear-gradient(135deg,#8a6d2f,#d6d0c2)}
/* üçlü kartlar */
.three{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.three>div,.fgrid>div{background:#fff;border:1px solid #f3f0e8;border-radius:3px;padding:22px;box-shadow:none}
.three b,.fgrid h3{display:block;font-size:18px;line-height:1.25;color:#161a21;margin:14px 0 6px;font-weight:800}
.three p,.fgrid p{color:#161a21;font-size:14.5px}
.fgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.note2{margin-top:18px;color:#161a21;font-size:14px}
.lt .sh{margin-bottom:22px}
/* demo */
.dform{background:#fff;color:#161a21;border-radius:3px;padding:24px;box-shadow:none}
.dform h2{font-size:22px;line-height:1.2;font-weight:800}
.dform>p{color:#161a21;font-size:14px;margin:6px 0 16px;max-width:none}
.dform .frm{display:grid;grid-template-columns:1fr 1fr;gap:12px;background:none;border-radius:0;padding:0}
.dform .frm>div:nth-child(3){grid-column:1/-1}
.dform .frm label{position:static;display:block;font-size:13px;font-weight:700;color:#161a21;margin-bottom:4px}
.dform .frm input,.dform .frm select,.dkk .frm input,.dkk .frm select{width:100%;height:46px;border:1.5px solid #7c8088;border-radius:3px;padding:0 12px;font-size:15px;background:#fff;color:#161a21}
.dform .frm .bt{grid-column:1/-1;width:100%}
.dform .frm small{grid-column:1/-1;color:#40444c;font-size:12.5px}
.dkk .frm .bt{color:#161a21}
.dpr{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:34px;align-items:center}
.dpr h2{font-size:30px;line-height:1.12;font-weight:800;color:#161a21;letter-spacing:-.015em}
.dpr p{color:#161a21;margin:12px 0 18px;max-width:480px}
.big{display:inline-block;font-size:30px;font-weight:800;color:#161a21}
.shot{background:#fff;border:1px solid #f3f0e8;border-radius:3px;overflow:hidden;box-shadow:none}
.shot img{width:100%;height:auto}
/* bayilik */
.us{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,.9fr);gap:44px;align-items:center}
.us h2{font-size:30px;line-height:1.12;font-weight:800;color:#161a21;letter-spacing:-.015em}
.seq{list-style:none;padding:0;margin:22px 0 0;position:relative;display:grid;gap:0}
.seq li{display:grid;grid-template-columns:46px 1fr;gap:16px;padding-bottom:24px;position:relative}
.seq li:last-child{padding-bottom:0}
.seq li:not(:last-child):before{content:"";position:absolute;left:22px;top:46px;bottom:2px;width:2px;background:#d6d0c2}
.seq i{display:none}
.seq time{width:46px;height:46px;border-radius:50%;display:grid;place-items:center;color:#fff;font-weight:800;font-size:20px;box-shadow:none}
.seq li:nth-child(1) time{background:linear-gradient(135deg,#8a6d2f,#8a6d2f)}
.seq li:nth-child(2) time{background:linear-gradient(135deg,#8a6d2f,#d6d0c2)}
.seq li:nth-child(3) time{background:linear-gradient(135deg,#3e6250,#6f9682)}
.seq b{display:block;font-size:18px;color:#161a21;font-weight:800;margin-top:2px}
.seq p{color:#161a21;font-size:14.5px;margin-top:2px}
.fis{background:#fff;border:1px solid #f3f0e8;border-radius:3px;padding:22px;box-shadow:none;border-top:6px solid #8a6d2f}
.fis .top{display:flex;justify-content:space-between;gap:12px;font-weight:800;font-size:17px;color:#161a21;padding-bottom:12px;margin-bottom:12px;border-bottom:1px solid #f3f0e8}
.fis .top span:last-child{font-weight:700;font-size:12px;background:#f5eee0;color:#8a6d2f;border-radius:2px;padding:3px 10px;align-self:center}
.fis dl{display:grid;grid-template-columns:1fr auto;gap:10px 14px;margin:0 0 14px}
.fis dt{color:#161a21;font-size:14px}.fis dd{margin:0;font-weight:700;color:#161a21;text-align:right}
.fis .ftr{font-weight:800;color:#3e6250;background:#eef3ee;border-radius:3px;padding:10px 14px}
.sss{display:grid;grid-template-columns:minmax(0,280px) minmax(0,1fr);gap:26px;align-items:start}
.sss h2{font-size:28px;line-height:1.15;font-weight:800;color:#161a21}
.sss>div{display:grid;gap:8px}
/* hata kodları */
.tool{display:grid;grid-template-columns:1fr 1fr;gap:12px;align-items:end;background:#fff;color:#161a21;border-radius:3px;padding:20px;margin-top:22px;max-width:620px;box-shadow:none}
.tool>div{min-width:0}
.tool label{display:block;font-size:13px;font-weight:700;color:#161a21;margin-bottom:4px}
.tool input,.tool select{width:100%;height:46px;border:1.5px solid #7c8088;border-radius:3px;padding:0 12px;font-size:15px;background:#fff;color:#161a21}
.tool .bt{width:100%}
.hk{background:#fff;border:1px solid #f3f0e8;border-radius:3px;overflow:hidden;box-shadow:none}
.hk .r{display:grid;grid-template-columns:110px 1.3fr 110px 1.5fr;gap:20px;padding:16px 22px;border-top:1px solid #f3f0e8;align-items:center;color:#161a21}
.hk .r.h{background:linear-gradient(100deg,#161a21,#8a6d2f);color:#fff;font-weight:700;font-size:13px;border:0;padding:13px 22px}
.hk .r[hidden]{display:none}
.hk .cd{justify-self:start;font-size:20px;font-weight:800;color:#8a6d2f;background:#f7f5ef;border-radius:3px;padding:5px 14px}
.lv{display:inline-block;font-weight:700;font-size:13px;padding:3px 12px;border-radius:2px;background:#f5eee0;color:#8a6d2f}
.lv.y{background:#ffe0e0;color:#9c1616}
.hk .none{padding:22px;font-weight:600}
.pgart{display:flex;gap:14px;justify-content:center;align-items:center}
.pgart svg{width:104px;height:104px;padding:12px;border-radius:3px;background:#fff;box-shadow:none}
.pgart svg:nth-child(2){margin-top:34px}
/* sektör kartları */
.sekw{background:linear-gradient(180deg,#f3f0e8,#f7f5ef)}
.sek{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.sek a{position:relative;display:flex;flex-direction:column;gap:6px;padding:20px;background:#fff;border-radius:3px;box-shadow:none;border:1px solid #f3f0e8;transition:transform .16s,box-shadow .16s}
.sek a:hover{transform:translateY(-3px);box-shadow:none}
.sek .ic{width:80px;height:80px;padding:11px;border-radius:3px;margin-bottom:8px;box-shadow:none}
.sek a:nth-child(1) .ic{background:linear-gradient(135deg,#8a6d2f,#c9ae75)}
.sek a:nth-child(2) .ic{background:linear-gradient(135deg,#8a6d2f,#8a6d2f)}
.sek a:nth-child(3) .ic{background:linear-gradient(135deg,#8a6d2f,#8a6d2f)}
.sek a:nth-child(4) .ic{background:linear-gradient(135deg,#8a6d2f,#d6d0c2)}
.sek a:nth-child(5) .ic{background:linear-gradient(135deg,#3e6250,#6f9682)}
.sek a:nth-child(6) .ic{background:linear-gradient(135deg,#8a6d2f,#8a6d2f)}
.sek a:nth-child(7) .ic{background:linear-gradient(135deg,#8a6d2f,#c9ae75)}
.sek a:nth-child(8) .ic{background:linear-gradient(135deg,#d23b6a,#ff7a9f)}
.sek b{font-size:18px;line-height:1.2;color:#161a21;font-weight:800}
.sek span{font-size:13.5px;line-height:1.4;color:#161a21}.sek em{font-style:normal}
.sek a>svg:last-child{position:absolute;right:16px;top:16px;width:34px;height:34px;padding:8px;border-radius:50%;background:#f7f5ef;color:#8a6d2f}
.sek a:hover>svg:last-child{background:#8a6d2f;color:#fff}
/* hata/sektör alt bandı */
.ctaw{background:#f7f5ef;padding:36px 0}
.cta2{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:28px;align-items:center;color:#fff;border-radius:3px;padding:28px 36px;background:radial-gradient(500px 300px at 85% 50%,#8a6d2f88,transparent 70%),linear-gradient(110deg,#161a21,#8a6d2f)}
.cta2 h2{font-size:28px;line-height:1.15;font-weight:800}.cta2 p{color:#f3f0e8;margin-top:6px;max-width:560px}
@media(max-width:1060px){
 .pgh h1{font-size:34px}
 .three,.fgrid{grid-template-columns:1fr 1fr}
 .dpr,.us,.sss{grid-template-columns:1fr}
 .sek{grid-template-columns:1fr 1fr}
 .pgart{justify-content:flex-start}
 .cta2{grid-template-columns:1fr}
}
@media(max-width:700px){
 main>section{padding:34px 0}
 .three,.fgrid{grid-template-columns:1fr}
 .sh h2,.dpr h2,.us h2{font-size:26px}
 .dform{padding:20px}.dform .frm,.tool{grid-template-columns:1fr}
 .dform .frm>div:nth-child(3){grid-column:auto}
 .hk .r.h{display:none}
 .hk .r{grid-template-columns:1fr;gap:6px;padding:16px 18px}
 .hk .r:not(.h)>div:nth-child(2):before{content:"Anlamı: ";font-weight:700}
 .hk .r:not(.h)>div:nth-child(4):before{content:"İlk kontrol: ";font-weight:700}
 .cta2{padding:24px 20px}.cta2 h2{font-size:24px}
 .pgart svg{width:84px;height:84px}
}
@media(max-width:560px){
 .sek{grid-template-columns:1fr}
 .sek a{display:grid;grid-template-columns:72px 1fr;column-gap:14px;row-gap:2px;align-items:center;padding:14px 56px 14px 14px}
 .sek .ic{grid-row:1/3;width:72px;height:72px;margin:0}
 .sek a>svg:last-child{top:50%;transform:translateY(-50%)}
 .big{font-size:26px}
}
/* ek sayfalar: gen_sayfalar.py */
.g5{grid-template-columns:1.5fr repeat(4,1fr)!important}
footer .fp{font-weight:800;font-size:18px;color:#fff;margin-top:6px}
@media(max-width:900px){.g5{grid-template-columns:1fr 1fr!important}.g5>div:first-child{grid-column:1/-1}}
.ctg{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.cc{display:block;background:#fff;border:1px solid var(--l);border-radius:3px;padding:26px;transition:transform .15s,box-shadow .15s}
.cc:hover{transform:translateY(-2px);box-shadow:none}
.cc b{display:block;font-size:17px;margin:12px 0 4px;color:var(--n)}.cc .cbig{display:block;font-size:22px;font-weight:800;color:var(--o);margin-bottom:6px}.cc p{color:#40444c}
.fc2{display:grid;grid-template-columns:1fr 1fr;gap:40px;align-items:start}.fc2 h2{font-size:30px;color:var(--n);margin-bottom:10px}
.tick{list-style:none;padding:0;margin:16px 0 0}.tick li{padding:6px 0 6px 26px;position:relative}.tick li:before{content:"";position:absolute;left:0;top:11px;width:14px;height:8px;border-left:3px solid var(--g);border-bottom:3px solid var(--g);transform:rotate(-45deg)}
.tg{font-size:20px;color:var(--n);margin:28px 0 12px}
.tmg{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.tm{display:block;background:#fff;border:1px solid var(--l);border-radius:3px;padding:18px;transition:transform .15s,box-shadow .15s}
.tm:hover{transform:translateY(-2px);box-shadow:none}
.tm .sw{display:flex;height:54px;border-radius:3px;overflow:hidden;margin-bottom:12px}.tm .sw i{flex:1}.tm .sw i+i{flex:.35}
.tm b{display:block;color:var(--n)}.tm small{color:#40444c}.tm .go{display:block;margin-top:10px;color:var(--o);font-weight:700;font-size:14px}
.blg{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.bl{display:block;background:#fff;border:1px solid var(--l);border-radius:3px;padding:24px;transition:transform .15s,box-shadow .15s}
.bl:hover{transform:translateY(-2px);box-shadow:none}.bl b{display:block;font-size:18px;color:var(--n);margin-bottom:8px}.bl p{color:#40444c}.bl .go{display:block;margin-top:12px;color:var(--o);font-weight:700}
.art{max-width:760px;margin:0 auto;font-size:17px;line-height:1.7}.art h2{font-size:24px;color:var(--n);margin:28px 0 8px}.art p,.art ul{margin:0 0 14px}.art ul{padding-left:22px}.art li{margin-bottom:6px}.art a{color:var(--b);text-decoration:underline}
.calc{display:grid;grid-template-columns:1.2fr 1fr;gap:28px;align-items:start}.calc .note2{grid-column:1/-1}
.cin{display:grid;grid-template-columns:1fr 1fr;gap:14px}.cin label{display:block;font-size:13px;font-weight:600;margin-bottom:4px;color:var(--n)}
.cin input{width:100%;padding:12px;border:1px solid #f3f0e8;border-radius:3px;font:inherit}.cin input:focus{outline:2px solid var(--b);border-color:var(--b)}
.cout{background:var(--n);color:#fff;border-radius:3px;padding:22px;display:grid;grid-template-columns:1fr auto;gap:10px 16px;margin:0}.cout dt{opacity:.8}.cout dd{margin:0;font-weight:800;text-align:right}
@media(max-width:900px){.ctg,.blg{grid-template-columns:1fr}.tmg{grid-template-columns:1fr 1fr}.fc2,.calc{grid-template-columns:1fr}.cin{grid-template-columns:1fr}}
@media(max-width:480px){.tmg{grid-template-columns:1fr}}
.ctg.c4{grid-template-columns:repeat(4,1fr)}.cc .go{display:block;margin-top:10px;color:var(--o);font-weight:700;font-size:14px}
@media(max-width:900px){.ctg.c4{grid-template-columns:1fr 1fr}}@media(max-width:480px){.ctg.c4{grid-template-columns:1fr}}
#daha{padding:56px 0;background:#f7f5ef}#daha .sh h2{font-size:30px;color:var(--n);margin-bottom:22px}
#daha .ib{display:none}#daha .cc{border-top:4px solid var(--o);padding:24px}#daha .cc:nth-child(2){border-top-color:var(--b)}#daha .cc:nth-child(3){border-top-color:var(--g)}#daha .cc:nth-child(4){border-top-color:var(--p)}
#daha .cc b{margin-top:0;font-size:19px}
/* ===== premium katmanı (eski sınıf sözlüğünün üstüne) ===== */
:root{--n:#14161a;--o:#8a6d2f;--o2:#6f5724;--b:#8a6d2f;--g:#5f8f78;--p:#8a6d2f;--l:#d6d0c2}
body.o7in{font:400 17px/1.55 var(--f);color:var(--ink);background:var(--iv)}
.o7in .w{max-width:1240px;padding:0 40px}
.o7in h1,.o7in h2,.o7in h3,.o7in h4{font-family:var(--f);color:var(--ink)}
.o7in h1,.o7in h2{font-weight:300;letter-spacing:-.035em}
.o7in h3,.o7in h4{font-weight:500;letter-spacing:-.01em}
.o7in section{padding-top:72px;padding-bottom:0}
.o7in .tint,.o7in .bnd:not(.sq){background:transparent}
.o7in .skip{position:absolute;left:-999px}.o7in .skip:focus{left:16px;top:12px;z-index:99;background:var(--ch);color:var(--g0);padding:10px 16px}
/* sayfa başlığı */
.o7in .pgh{background:var(--g0);color:#fff;border-bottom:1px solid var(--hl)}
.o7in .pgh .w{padding-top:64px;padding-bottom:72px;grid-template-columns:minmax(0,1fr)}
.o7in .pgh h1{font-size:clamp(38px,5.4vw,78px);line-height:1.04;color:#fff;max-width:900px}
.o7in .pgh p{color:#b9bec8;font-size:20px;max-width:640px;line-height:1.55;margin:22px 0 28px}
.o7in .crumb{font-size:14px;color:var(--mutd);margin-bottom:22px;display:flex;gap:8px;align-items:center}
.o7in .crumb a{color:var(--ch)}.o7in .crumb a:hover{color:#fff}
.o7in .pga{display:none}
.o7in .pgh .ticks{margin:0 0 8px}.o7in .pgh .ticks li{color:#d3d7de}
.o7in .pgh .jump a{border:1px solid var(--hl2);background:transparent;color:#d3d7de;border-radius:0;padding:9px 16px;font-weight:500}
.o7in .pgh .jump a:hover{border-color:var(--ch);color:var(--ch);background:transparent}
/* düğmeler */
.o7in .pill,.o7in .bt,.o7in a.bt{border-radius:0;background:var(--ch);color:var(--g0);border:1px solid var(--ch);font-weight:500;font-size:15px;min-height:48px;padding:0 24px;display:inline-flex;align-items:center;justify-content:center;gap:8px;transition:background-color .25s var(--ease),color .25s var(--ease)}
.o7in .pill:hover,.o7in .bt:hover{background:transparent;color:var(--chd);border-color:var(--chd)}
.o7in .pgh .pill:hover,.o7in .dkk .pill:hover,.o7in .cta2 .pill:hover,.o7in .dkk .bt:hover{color:var(--ch);border-color:var(--ch)}
.o7in .pill.ol,.o7in .gh,.o7in .ol{background:transparent;color:var(--chd);border:1px solid var(--chd);border-radius:0}
.o7in .pill.ol:hover,.o7in .gh:hover{background:var(--chd);color:#fff}
.o7in .pill.s{min-height:42px;padding:0 18px;font-size:14px}
/* kartlar */
.o7in .fgrid>div,.o7in .cc,.o7in .cbig,.o7in .art,.o7in .tool,.o7in .calc,.o7in .set,.o7in .fis,.o7in .dform,.o7in .frm,.o7in .shot,.o7in .sw,.o7in .tm,.o7in .rel a,.o7in .oth a,.o7in .chp,.o7in .bl,.o7in .blg>*,.o7in .mod,.o7in .pkh{background:#fbf9f4;border:1px solid #d6d0c2;border-radius:0;box-shadow:none}
.o7in .frm{background:#fbf9f4}
.o7in .fgrid>div{padding:26px}
.o7in .fgrid h3{font-size:19px;color:var(--ink)}
.o7in .fgrid p{color:var(--mut)}
.o7in .fgrid a{color:var(--chd);font-weight:500}
.o7in .ib{background:none!important;color:var(--chd);border:1px solid #cfc9ba;border-radius:0;width:46px;height:46px}
.o7in .ib svg{stroke-width:1.5}
.o7in .sh h2,.o7in h2.sh{font-size:clamp(32px,4.2vw,56px);line-height:1.06;margin-bottom:14px}
.o7in .sh p,.o7in .sh .lede{color:var(--mut);font-size:18px;max-width:640px}
.o7in .sh .k,.o7in .eyebrow{font-size:14px;color:var(--chd);font-weight:500;letter-spacing:0;text-transform:none}
/* koyu şerit / CTA */
.o7in .cta2,.o7in .dkk{background:var(--g0);color:#fff;border-radius:0;border:1px solid var(--g0)}
.o7in .cta2 h2,.o7in .dkk h2,.o7in .dkk h3{color:#fff;font-weight:300}
.o7in .cta2 p,.o7in .dkk p{color:#aeb3bd}
.o7in .cta2 .pill,.o7in .dkk .pill{background:var(--ch);color:var(--g0)}
.o7in .cta2{padding:44px 48px}
.o7in .ctab,.o7in .cta{background:var(--g0);color:#fff;border-radius:0}
.o7in .ctab h2,.o7in .cta h2{color:#fff;font-weight:300}
/* form */
.o7in input,.o7in select,.o7in textarea{border-radius:0;border:1px solid #cfc9ba;background:#fff;font:400 16px var(--f);min-height:48px;padding:10px 14px;color:var(--ink)}
.o7in input:focus,.o7in select:focus,.o7in textarea:focus{outline:2px solid var(--ch);outline-offset:0;border-color:var(--chd)}
.o7in label{font:500 14px var(--f);color:#41444b}
.o7in .dkk .frm,.o7in .dkk .dform,.o7in .cta2 .frm,.o7in .dform{background:#fbf9f4;color:var(--ink)}
.o7in .dkk .frm label,.o7in .dform label{color:#41444b}
/* tablo / paket */
.o7in .pr,.o7in .fy,.o7in .cmp{border-radius:0}
.o7in table{border-collapse:collapse}
.o7in .cmp th,.o7in .cmp thead th{background:var(--g0);color:#fff;font-weight:500;border-radius:0}
.o7in .cmp .hot,.o7in .cmp td.hot{background:rgba(201,174,117,.14)}
.o7in .cmp .y,.o7in .y{color:var(--chd)}
.o7in .cmp .y svg,.o7in .cmp td svg{fill:var(--chd)}
.o7in .cmp svg circle,.o7in .cmp svg rect{fill:var(--chd)}
.o7in .fp{border-radius:0;border:1px solid #d6d0c2;background:#fbf9f4}
.o7in .fp.hot{border-color:var(--chd);background:#fbf9f4}
.o7in .fp .ph{background:var(--g0);color:#fff;border-radius:0}
.o7in .fp.hot:before{background:var(--chd);color:#fff;border-radius:0}
/* SSS */
.o7in details{border:0;border-bottom:1px solid #cfc9ba;background:transparent;border-radius:0}
.o7in details summary{font:400 19px var(--f);color:var(--ink);padding:18px 0}
.o7in .sss details{border-left:0;padding-left:0}
.o7in .sss summary:after{color:var(--chd)}
/* makale / yasal metin */
.o7in .art,.o7in .lg{max-width:780px}
.o7in .art{background:transparent;border:0;padding:0}
.o7in .art h2{font-size:34px;margin:40px 0 12px}.o7in .art p,.o7in .art li{color:#34373e;line-height:1.7;font-size:18px}
