.o7in .pgh .ticks li:nth-child(1){animation-delay:.55s}.o7in .pgh .ticks li:nth-child(2){animation-delay:.65s}.o7in .pgh .ticks li:nth-child(3){animation-delay:.75s}.o7in .pgh .ticks li:nth-child(4){animation-delay:.85s}
.o7in .pgh .skv{animation:o7u 1.1s var(--ease) .5s both}
