.o7in .pgh .skv .fis .top,.o7in .pgh .skv .fis dt,.o7in .pgh .skv .fis dd,.o7in .pgh .skv .fis .tot{color:#d9dce2}
.o7in .pgh .skv .fis .top{border-bottom:1px solid var(--hl2)}
.o7in .pgh .skv .ln{animation:o7s .7s var(--ease) both}
.o7in .pgh .skv .ln:nth-of-type(1){animation-delay:1s}.o7in .pgh .skv .ln:nth-of-type(2){animation-delay:1.25s}.o7in .pgh .skv .ln:nth-of-type(3){animation-delay:1.5s}.o7in .pgh .skv .ln:nth-of-type(4){animation-delay:1.75s}
.o7in .pgh .skv .tot{animation:o7u .8s var(--ease) 2s both}
.o7in .pgh .skv>svg{display:none}
.o7in .pgh .skv .fis:after{content:"";display:block;height:1px;margin-top:14px;background:var(--ch);transform-origin:left;transform:scaleX(0);animation:o7g 1.6s var(--ease) 1.2s forwards}
@media(min-width:1000px){.o7in .pgh .w:has(.skv){grid-template-columns:minmax(0,1.15fr) minmax(0,.85fr);gap:56px;align-items:center}}
@keyframes o7u{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:none}}
@keyframes o7s{from{opacity:0;transform:translateX(-14px)}to{opacity:1;transform:none}}
@keyframes o7f{to{opacity:.45}}
@keyframes o7g{to{transform:scaleX(1)}}
@keyframes o7h{from{opacity:0;transform:translateY(46px);clip-path:inset(0 0 100% 0)}to{opacity:1;transform:none;clip-path:inset(-12% 0 -12% 0)}}
@media(prefers-reduced-motion:reduce){.o7in .pgh *,.o7in .pgh:before,.o7in .pgh:after{animation:none!important;opacity:1!important;transform:none!important;clip-path:none!important}}
.o7in .fgrid p:last-of-type{border-radius:0!important}
.o7in .pgh .skv .fis .tot{background:var(--g2)!important;color:var(--ch)!important;border-top:1px solid var(--hl2)}
.o7in .fis,.o7in .fis .tot{border-radius:0}

inner.mobil-yeni-ic2.css:
.vb{display:none}
