:root{--n:#161a21;--o:#8a6d2f;--o2:#8a6d2f;--b:#8a6d2f;--g:#3e6250;--p:#8a6d2f;--l:#f3f0e8}
*{box-sizing:border-box;margin:0}
body{font:400 15px/1.5 'Segoe UI',system-ui,-apple-system,Roboto,Arial,sans-serif;color:#161a21;background:#fff}
img{max-width:100%;height:auto;display:block}a{color:inherit;text-decoration:none}
.w{max-width:1240px;margin:0 auto;padding:0 28px}
header{background:#fff;border-bottom:1px solid var(--l);position:sticky;top:0;z-index:20}
.hr{display:flex;align-items:center;gap:30px;height:82px}.hr img{height:52px;width:auto}
.hr nav{display:flex;gap:26px;margin-left:34px;font-weight:600;font-size:14px}.hr nav a:hover{color:var(--o)}
.hr .r{margin-left:auto;display:flex;align-items:center;gap:22px}
.tel{font-weight:700;font-size:14px;white-space:nowrap}
.pill{display:inline-flex;align-items:center;justify-content:center;gap:8px;background:var(--o);color:#fff;font-weight:700;border-radius:2px;padding:11px 22px;border:0;cursor:pointer;font-size:14px}
.pill:hover{background:var(--o2)}.pill.s{padding:9px 18px;font-size:13px}
.pill.ol{background:#fff;color:var(--o2);border:1.5px solid var(--o)}
.burger{display:none;margin-left:auto;background:0;border:0;padding:8px;color:var(--n)}.burger svg{display:block;stroke:var(--n)}
/* hero */
.hero{background:linear-gradient(100deg,#0a0c0f 0%,#161a21 38%,#40444c 70%,#7c8088 100%);color:#fff;position:relative;overflow:hidden}
.hero:before{content:"";position:absolute;right:-80px;top:-60px;width:620px;height:620px;background:radial-gradient(circle,#ffffff40,transparent 65%)}
.hg{display:grid;grid-template-columns:.9fr 1.1fr;gap:20px;align-items:center;position:relative;padding:48px 28px 64px}
.hg>*{min-width:0}
.hero h1{font-size:50px;line-height:1.08;font-weight:800;letter-spacing:-.02em}.hero h1 span{color:var(--o);display:block}
.hero p{margin:18px 0 22px;font-size:18px;color:#f3f0e8;max-width:480px}.hero p b{color:#fff;display:block;margin-top:6px}
.cta{display:flex;gap:26px;align-items:center;flex-wrap:wrap}.cta .tl{font-weight:700;display:flex;gap:10px;align-items:center}
.cta .tl svg{width:20px;height:20px;stroke:var(--o);fill:none;stroke-width:2}
.dv{position:relative;height:400px}
.lap{position:absolute;left:0;top:14px;width:84%;transform:perspective(1400px) rotateY(-14deg) rotateX(3deg);transform-origin:left center}
.lap .sc{background:#0a0c0f;border:7px solid #161a21;border-radius:3px 12px 2px 2px;aspect-ratio:16/10;overflow:hidden;box-shadow:none}
.lap:after{content:"";display:block;height:12px;margin:0 -6%;background:linear-gradient(#f3f0e8,#7c8088);border-radius:0 0 16px 16px}
.dash{display:grid;grid-template-columns:44px 1fr;height:100%;font-size:7px;background:#f7f5ef;color:#161a21}
.dash .sb{background:#161a21;padding:10px 0;display:grid;gap:7px;align-content:start;justify-items:center}.dash .sb i{width:18px;height:3px;background:#40444c;border-radius:2px}.dash .sb i:first-child{background:var(--o);height:10px;width:10px;border-radius:3px}
.dash .mn{padding:10px;display:grid;gap:7px;align-content:start}
.dash .st4{display:grid;grid-template-columns:repeat(4,1fr);gap:6px}
.dash .st4 div{border-radius:3px;padding:6px 7px;color:#fff;font-weight:700;font-size:6.5px}.dash .st4 b{display:block;font-size:13px;margin-top:2px}
.dash .row2{display:grid;grid-template-columns:1.6fr 1fr;gap:6px}
.dash .bx{background:#fff;border-radius:3px;padding:6px}.dash .bx svg{display:block;width:100%}
.dash .tb div{display:flex;justify-content:space-between;border-top:1px solid #f7f5ef;padding:3px 0;font-size:6.5px}
.ph{position:absolute;right:0;bottom:0;width:150px;background:#0a0c0f;border:5px solid #161a21;border-radius:3px;padding:10px 7px;box-shadow:none;color:#161a21}
.ph .sc2{background:#f7f5ef;border-radius:3px;padding:9px;font-size:9px;min-height:250px}
.ph .sc2>b{display:block;font-size:11px;margin-bottom:6px}
.ph .it{background:#fff;border-radius:3px;padding:6px 7px;margin-top:5px;display:flex;justify-content:space-between;gap:4px;align-items:center}
.ph .it small{display:block;color:#40444c;font-size:8px}
.bd{font-size:8px;font-weight:700;border-radius:3px;padding:1px 5px;background:#eef3ee;color:#3e6250;white-space:nowrap}.bd.o{background:#f5eee0;color:#8a6d2f}.bd.b{background:#f3f0e8;color:#8a6d2f}
/* sector strip */
.ss{background:#f7f5ef;border-bottom:1px solid var(--l)}
.ssg{display:grid;grid-template-columns:190px 1fr;gap:18px;align-items:center;padding:16px 28px}
.ssg h2{font-size:17px;line-height:1.25;background:#fff;border-radius:3px;padding:16px 18px;box-shadow:none}
.sg{display:grid;grid-template-columns:repeat(8,1fr);gap:8px}
.sg a{display:flex;flex-direction:column;align-items:center;gap:6px;padding:11px 2px;border-radius:3px;font-weight:600;font-size:13px;background:#fff;box-shadow:none}
.sg a:hover{box-shadow:none}
.sg svg{width:28px;height:28px;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
/* bands */
.bandw{padding:34px 0}.bandb{padding:34px 0;background:linear-gradient(180deg,#f7f5ef,#fff)}
h2.t{font-size:30px;line-height:1.12;letter-spacing:-.015em;color:var(--n);font-weight:800}
.lead{color:#40444c;margin:10px 0 12px}
.ck{list-style:none;padding:0;display:grid;gap:5px;margin-bottom:16px;font-weight:500}.ck li:before{content:"✓";color:var(--o);font-weight:800;margin-right:9px}
.r3{display:grid;grid-template-columns:330px 1fr 280px;gap:26px;align-items:center}.r3>*{min-width:0}
.tab{background:#161a21;border-radius:3px;padding:8px;box-shadow:none}
.tab .in{background:#fff;border-radius:3px;padding:16px;display:grid;gap:12px}
.tab h3{font-size:16px}
.td{display:grid;grid-template-columns:48px 1fr 1fr 22px;gap:8px;align-items:center;padding:8px 0;border-bottom:1px solid #f7f5ef;font-size:13px}
.ck2{width:20px;height:20px;border-radius:50%;border:2px solid #d6d0c2;display:block}.ck2.on{background:var(--g);border-color:var(--g);position:relative}.ck2.on:after{content:"✓";color:#fff;position:absolute;inset:0;font-size:12px;text-align:center;line-height:16px}
.tm{display:grid;grid-template-columns:1fr 1fr;gap:10px}.tm div{background:#f7f5ef;border-radius:3px;padding:10px 12px;font-size:12px;font-weight:600}.tm b{display:block;font-size:24px}
.kz{background:#fff;border-radius:3px;box-shadow:none;padding:22px;text-align:center}
.kz .rk{width:54px;height:54px;border-radius:50%;background:#f5eee0;margin:0 auto 8px;display:grid;place-items:center}
.kz .rk svg{width:28px;height:28px;stroke:var(--o2);fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.kz h3{font-size:18px}.kz p{font-size:13px;color:#40444c;margin:6px 0 14px}
.stp{display:flex;align-items:center;justify-content:center}
.stp i{width:14px;height:14px;border-radius:50%;border:2px solid #d6d0c2;background:#fff;flex:none}.stp i.d{background:var(--o);border-color:var(--o)}.stp i.c{border-color:var(--b)}
.stp u{height:2px;width:30px;background:#d6d0c2}.stp u.d{background:var(--b)}
.r4{display:grid;grid-template-columns:280px 1fr 190px;gap:24px;align-items:center}.r4>*{min-width:0}
.tl4{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;position:relative}
.tl4:before{content:"";position:absolute;left:24px;right:24px;top:24px;height:2px;background:#f3f0e8}
.tl4 .st{position:relative}.tl4 .ic{width:48px;height:48px;border-radius:50%;background:#fff;box-shadow:none;display:grid;place-items:center;margin-bottom:10px;position:relative}
.tl4 .ic svg{width:24px;height:24px;fill:none;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}
.tl4 time{font-weight:800;font-size:16px;display:block}.tl4 span{font-size:13px;color:#40444c;display:block}
.ph2{width:178px;margin:0 auto;background:#0a0c0f;border:5px solid #161a21;border-radius:3px;padding:9px 7px}
.ph2 .sc2{background:#fff;border-radius:3px;padding:10px;font-size:9px}
.sig{height:70px;border:1px dashed #d6d0c2;border-radius:3px;margin:8px 0}.sig svg{width:100%;height:100%}
.r5{display:grid;grid-template-columns:230px 250px 1fr;gap:20px;align-items:center}.r5>*{min-width:0}
.col{position:relative;height:190px}.col img{position:absolute;border-radius:3px;box-shadow:none;border:1px solid var(--l);background:#fff}
.col img:nth-child(1){left:0;top:0;width:150px}.col img:nth-child(2){left:70px;top:40px;width:160px;z-index:2}.col img:nth-child(3){left:20px;top:100px;width:150px;z-index:3}
.pr{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}
.pr>h2{grid-column:1/-1;font-size:22px;margin-bottom:-2px}
.pc{background:#fff;border-radius:3px;overflow:hidden;box-shadow:none;display:flex;flex-direction:column;position:relative}
.pc h3{background:var(--n);color:#fff;padding:12px 14px;font-size:14px}
.pc h3 b{display:block;font-size:20px;margin-top:2px}.pc h3 small{font-size:11px;font-weight:600;opacity:.8}
.pc:nth-child(3) h3{background:#8a6d2f}.pc.pop h3{background:var(--o)}
.pc .tag{position:absolute;right:8px;top:8px;background:#fff;color:var(--o2);font-size:10px;font-weight:800;border-radius:2px;padding:2px 8px}
.pc ul{list-style:none;padding:12px 14px;display:grid;gap:5px;font-size:12.5px;flex:1}.pc li:before{content:"✓";color:var(--o);font-weight:800;margin-right:6px}
.pc .pill{margin:0 12px 12px;background:#fff;color:var(--n);border:1.5px solid #f3f0e8;padding:8px;font-size:12px}.pc.pop .pill{background:var(--o);color:#fff;border-color:var(--o)}
.fqg{display:grid;grid-template-columns:200px 1fr 1fr;gap:20px;align-items:start}.fqg>*{min-width:0}
.fqg h2{font-size:24px;line-height:1.15}
.fqc{display:grid;gap:8px}
details{background:#fff;border-radius:3px;box-shadow:none}
summary{cursor:pointer;padding:11px 14px;font-weight:600;font-size:13.5px;list-style:none;display:flex;justify-content:space-between;gap:10px}
summary:after{content:"+";color:var(--o2);font-size:18px;line-height:1}details[open] summary:after{content:"–"}
details p{padding:0 14px 12px;color:#40444c;font-size:13px}
.cb{background:linear-gradient(110deg,#161a21,#40444c);border-radius:3px;color:#fff;padding:28px 36px;display:grid;grid-template-columns:1.2fr 1fr;gap:28px;align-items:center;margin:8px 0 28px}
.cb>*{min-width:0}.cb h2{font-size:30px;line-height:1.15}.cb h2 span{color:var(--o)}.cb p{color:#f3f0e8;margin-top:6px}
.frm{display:flex;gap:0;background:#fff;border-radius:2px;padding:5px;align-items:center}
.frm div{flex:1}.frm label{position:absolute;left:-9999px}
.frm input{width:100%;height:44px;border:0;padding:0 20px;font-size:15px;background:transparent;outline:0;color:#161a21}
footer{background:var(--n);color:#d6d0c2;padding:28px 0;font-size:13px}footer .w{display:flex;justify-content:space-between;gap:18px;flex-wrap:wrap}footer a{margin-right:16px}
@media(max-width:1060px){.hr nav,.hr .r{display:none}.burger{display:block}
.hg{grid-template-columns:1fr;padding:40px 24px 56px}.hero h1{font-size:38px}.dv{height:360px}
.ssg{grid-template-columns:1fr}.sg{grid-template-columns:repeat(4,1fr)}
.r3,.r4,.r5,.fqg,.cb{grid-template-columns:1fr}.pr{grid-template-columns:1fr 1fr}.col{height:210px;max-width:260px}}
@media(max-width:560px){.w{padding:0 18px}.hg{padding:36px 18px 52px}.hero h1{font-size:32px}.hero p{font-size:16px}.dv{height:300px}.ph{width:120px}.ph .sc2{min-height:190px}
.sg{gap:6px}.sg a{font-size:11px}.tl4{grid-template-columns:1fr 1fr;row-gap:20px}.tl4:before{display:none}.pr{grid-template-columns:1fr}.cb{padding:24px 20px}.cb h2{font-size:25px}
h2.t{font-size:26px}.td{grid-template-columns:44px 1fr 22px}.td span:nth-child(3){display:none}}
.pc.pop h3{padding-top:26px}.pc .tag{top:6px;left:14px;right:auto}
