/* form bölümü */
.dkk{background:radial-gradient(500px 300px at 85% 40%,#8a6d2f77,transparent 70%),linear-gradient(110deg,#161a21,#8a6d2f);color:#fff;padding:44px 0}
.dkk .fc{display:grid;grid-template-columns:1fr 1fr;gap:34px;align-items:center}.dkk .fc>*{min-width:0}
.dkk h2{font-size:32px;line-height:1.15}.dkk p{color:#f3f0e8;margin:8px 0 16px}
.dkk .big{display:inline-block;font-size:30px;font-weight:800;color:#8a6d2f}
.dkk .frm,.frm.st{display:grid;grid-template-columns:1fr 1fr;gap:12px;background:#fff;border-radius:3px;padding:20px;color:#161a21;box-shadow:none}
.dkk .frm label{position:static;font-size:13px;font-weight:700;color:#161a21;display:block;margin-bottom:4px;left:auto}
.dkk .frm input,.dkk .frm select{width:100%;height:46px;border:1.5px solid #f3f0e8;border-radius:3px;padding:0 12px;font-size:15px;background:#fff;color:#161a21;margin:0}
.dkk .frm .bt{grid-column:1/-1;justify-self:stretch;text-align:center;display:inline-flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#8a6d2f,#8a6d2f);color:#fff;font-weight:800;border-radius:2px;padding:14px;cursor:pointer;box-shadow:none}
.dkk .frm small{grid-column:1/-1;color:#40444c;font-size:12px}
@media(max-width:1060px){.dkk .fc{grid-template-columns:1fr}.dkk .frm{grid-template-columns:1fr}.dkk h2{font-size:26px}}
/* altbilgi */
footer{background:#161a21;color:#d6d0c2;padding:44px 0 26px;font-size:14px}
footer .w{display:block}footer .g{display:grid;grid-template-columns:1.4fr 1fr 1fr 1fr;gap:28px}
footer .g>*{min-width:0}footer p{margin-top:12px;max-width:300px;line-height:1.5}
footer h5{color:#fff;font-size:14px;margin-bottom:10px}footer .g a{display:block;margin:0 0 7px;color:#d6d0c2}footer .g a:hover{color:#8a6d2f}
footer .cp{display:flex;justify-content:space-between;gap:12px;border-top:1px solid #ffffff22;margin-top:26px;padding-top:16px;font-size:13px}
@media(max-width:700px){footer .g{grid-template-columns:1fr 1fr}footer .g>div:first-child{grid-column:1/-1}}
@media(max-width:1060px){.mn-f{background:transparent;border-top:1px solid #ffffff2a}.mn-l{border:0}}
/* erişilebilir turuncu: beyaz yazı >= 4.5:1 */
.pill,.pc.pop .pill,.dkk .frm .bt,.mn-c{background:linear-gradient(135deg,#8a6d2f,#8a6d2f);color:#fff}
.pill.ol{background:#fff;color:#8a6d2f}
.pc.pop h3{background:linear-gradient(135deg,#8a6d2f,#8a6d2f)}
.pc .tag{color:#8a6d2f}
.pc .pill{background:#fff;color:#161a21}.pc.pop .pill{background:linear-gradient(135deg,#8a6d2f,#8a6d2f);color:#fff}
@media(max-width:1060px){.vb .p2{background:linear-gradient(100deg,#3e6250,#3e6250)}}
footer .g img{height:34px;width:auto}
/* geliştirme: cila */
html{scroll-behavior:smooth;scroll-padding-top:84px}
header{transition:box-shadow .2s}header.sc{box-shadow:none}
header nav.m a{position:relative;padding:6px 0}
header nav.m a:after{content:"";position:absolute;left:0;right:0;bottom:-2px;height:2px;background:var(--o);transform:scaleX(0);transition:transform .2s;transform-origin:left}
header nav.m a:hover:after,header nav.m a[aria-current]:after{transform:scaleX(1)}
.pill{transition:transform .15s,box-shadow .15s,filter .15s}.pill:hover{transform:translateY(-1px);filter:brightness(1.05)}.pill:active{transform:translateY(1px)}
.sg a,.pc,details,.kz{transition:transform .18s,box-shadow .18s}
.sg a:hover,.pc:hover{transform:translateY(-3px)}
.pc.pop:hover{transform:translateY(-7px)}
input:focus,select:focus{outline:3px solid #8a6d2f;outline-offset:1px}
.frm [aria-invalid=true]{border-color:#b42318!important}
details[open] summary{color:var(--o2)}
@media(prefers-reduced-motion:reduce){*{transition:none!important;scroll-behavior:auto!important}}
:root{--o2:#8a6d2f}
.tsx div:nth-child(1){background:#8a6d2f!important}.tsx div:nth-child(2){background:#8a6d2f!important}.tsx div:nth-child(3){background:#3e6250!important}.tsx div:nth-child(4){background:#8a6d2f!important}

.yz{padding:48px 0 72px}.yz .w{max-width:820px}.yz h2{font-size:22px;color:var(--n);margin:30px 0 8px}.yz p{font-size:16px;line-height:1.7;color:#161a21}.yz a{color:var(--o2);text-decoration:underline}.yz .nt{background:#f5eee0;border-left:4px solid var(--o);padding:12px 16px;border-radius:3px;font-size:14px}
/* sektor-*.html — yeni.css üzerine sektör sayfası bileşenleri */
main{--ac:#8a6d2f;--ad:#8a6d2f}
main.a-kombi{--ac:#8a6d2f;--ad:#8a6d2f}
main.a-klima{--ac:#8a6d2f;--ad:#8a6d2f}
main.a-beyaz-esya{--ac:#8a6d2f;--ad:#8a6d2f}
main.a-elektronik{--ac:#8a6d2f;--ad:#8a6d2f}
main.a-bilgisayar{--ac:#3e6250;--ad:#3e6250}
main.a-tesisat{--ac:#3e6250;--ad:#161a21}
main.a-elektrik{--ac:#8a6d2f;--ad:#8a6d2f}
main.a-guvenlik{--ac:#d23b6a;--ad:#be1e56}

/* ---- hero (.pgh) ---- */
.pgh .w{padding-top:46px;padding-bottom:52px;gap:44px}
.pgh h1{max-width:620px}
.pgh .ticks li{display:flex;gap:10px;font-weight:500;color:#fff}
.pgh .ticks li:before{flex:none}
.ctas{display:flex;flex-wrap:wrap;gap:14px;margin-top:26px}
.ctas .pill{padding:13px 26px;font-size:15px}
.pill.gh{background:#ffffff1f;box-shadow:none;color:#fff}
.pill.gh:hover{background:#ffffff38}
.skv{position:relative;padding:68px 22px 22px;border-radius:3px;background:linear-gradient(160deg,#ffffff2e,#ffffff12);box-shadow:none}
.skic{position:absolute;right:26px;top:-22px;width:88px;height:88px;padding:11px;border-radius:3px;background:#fff;box-shadow:none;z-index:2}
.fis{background:#fff;color:#161a21;border-radius:3px;overflow:hidden;box-shadow:none}
.fis .top{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;background:var(--ad);color:#fff;font-weight:800;font-size:13px;padding:13px 18px}
.fis dl{display:grid;grid-template-columns:76px minmax(0,1fr);gap:7px 12px;padding:16px 18px 6px;font-size:14px}
.fis dt{color:#40444c;font-weight:600}.fis dd{font-weight:700;margin:0;overflow-wrap:anywhere}
.fis .ln{display:grid;grid-template-columns:48px minmax(0,1fr);gap:12px;align-items:center;padding:7px 18px;font-size:13.5px;position:relative}
.fis dl+.ln{border-top:1px dashed #d6d0c2;margin-top:8px;padding-top:14px}
.fis .ln time{font-weight:800;color:var(--ad)}
.fis .ln span{position:relative;padding-left:16px}
.fis .ln span:before{content:"";position:absolute;left:0;top:.45em;width:8px;height:8px;border-radius:50%;background:var(--ac)}
.fis .tot{margin-top:8px;padding:14px 18px;background:#f7f5ef;font-weight:800;font-size:17px;text-align:right}

/* ---- ortak bant düzeni: solda başlık, sağda içerik ---- */
.bnd{padding:40px 0}
.bnd>.w{display:grid;grid-template-columns:minmax(0,270px) minmax(0,1fr);gap:34px;align-items:start}
.sh.one h2{font-size:28px;line-height:1.15;letter-spacing:-.015em;font-weight:800;color:var(--n)}
.sh.one h2:before{content:"";display:block;width:46px;height:5px;border-radius:3px;background:linear-gradient(90deg,var(--ac),#8a6d2f);margin-bottom:14px}

/* sorunlar */
.pb{background:linear-gradient(180deg,#fff,#f7f5ef)}
.fgrid{display:grid;gap:14px;counter-reset:f}
.fgrid>div{counter-increment:f;display:grid;grid-template-columns:48px minmax(0,1fr) minmax(0,.95fr);column-gap:18px;row-gap:4px;align-items:start;background:#fff;border:1px solid #f3f0e8;border-radius:3px;padding:18px 20px;box-shadow:none}
.fgrid>div:before{content:counter(f);grid-row:1/3;width:44px;height:44px;border-radius:3px;display:grid;place-items:center;font-size:20px;font-weight:800;color:#fff;background:linear-gradient(135deg,#8a6d2f,#8a6d2f);box-shadow:none}
.fgrid>div:nth-child(2):before{background:linear-gradient(135deg,#8a6d2f,#8a6d2f);box-shadow:none}
.fgrid>div:nth-child(3):before{background:linear-gradient(135deg,#8a6d2f,#8a6d2f);box-shadow:none}
.fgrid h3{grid-column:2;font-size:17px;line-height:1.25;color:var(--n);align-self:end}
.fgrid p{font-size:14px;color:#161a21}
.fgrid p:first-of-type{grid-column:2}
.fgrid p:last-of-type{grid-column:3;grid-row:1/3;align-self:stretch;background:#eef3ee;border-left:4px solid #3e6250;border-radius:3px 12px 12px 4px;padding:11px 14px;color:#3e6250}
.fgrid p b{color:#3e6250}

/* hazır gelenler */
.tint{background:linear-gradient(180deg,#f3f0e8,#f7f5ef)}
.set{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:18px;align-items:stretch}
.set>div{border-radius:3px;padding:22px 24px}
.set>div:first-child{background:#fff;box-shadow:none}
.set>div:last-child{color:#fff;background:radial-gradient(300px 200px at 90% 0,#40444c77,transparent 70%),linear-gradient(150deg,#161a21,#40444c);box-shadow:none}
.set h3{font-size:16px;margin-bottom:12px;color:var(--n)}
.set>div:last-child h3{color:#fff}
.set h3[style]{margin-top:24px!important}
.chp{display:flex;flex-wrap:wrap;gap:8px}
.chp span{background:#f7f5ef;color:#40444c;font-weight:700;font-size:13px;border-radius:2px;padding:6px 13px}
.chp+h3+.chp span{background:#f5eee0;color:#8a6d2f}
.set .ticks{list-style:none;padding:0;display:grid;gap:0}
.set .ticks li{display:flex;gap:10px;padding:9px 0;border-bottom:1px solid #ffffff24;font-weight:500}
.set .ticks li:last-child{border:0}
.set .ticks li:before{content:"✓";color:#8a6d2f;font-weight:800}
.note2{margin-top:12px;font-size:13px;color:#f3f0e8}

/* akış */
.sq{background:radial-gradient(500px 320px at 100% 0,#40444c55,transparent 70%),linear-gradient(100deg,#161a21 0%,#161a21 60%,#8a6d2f 100%);color:#fff}
.sq .sh.one h2{color:#fff}
.seq{list-style:none;padding:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px;counter-reset:q}
.seq li{counter-increment:q;position:relative}
.seq i{display:grid;place-items:center;width:46px;height:46px;border-radius:50%;margin-bottom:12px;color:#fff;font-style:normal;font-weight:800;font-size:19px;box-shadow:none;position:relative;z-index:1;background:#8a6d2f}
.seq i:before{content:counter(q)}
.seq li:nth-child(2) i{background:#8a6d2f}.seq li:nth-child(3) i{background:#8a6d2f}.seq li:nth-child(4) i{background:#3e6250}
.seq li:not(:last-child):after{content:"";position:absolute;top:22px;left:62px;right:-12px;height:2px;background:#8a6d2f}
.seq time{display:block;font-weight:800;font-size:18px;color:#c9ae75}
.seq b{display:block;font-size:16px;margin:2px 0 4px}
.seq p{font-size:14px;color:#f7f5ef}

/* paket bandı */
.ctab{padding:36px 0}
.cta2{display:flex;align-items:center;justify-content:space-between;gap:28px;border-radius:3px;padding:28px 36px;color:#fff;background:radial-gradient(420px 260px at 100% 50%,#8a6d2f66,transparent 70%),linear-gradient(110deg,#161a21,#40444c);box-shadow:none}
.cta2>div{min-width:0}.cta2 h2{font-size:28px;line-height:1.15}.cta2 p{margin-top:8px;color:#f7f5ef;max-width:620px}
.cta2 .pill{flex:none;padding:14px 28px;font-size:15px}

/* sss */
#sss{padding:40px 0}
.sss{display:grid;grid-template-columns:minmax(0,270px) minmax(0,1fr);gap:34px;align-items:start}
.sss h2{font-size:28px;line-height:1.15;letter-spacing:-.015em;color:var(--n)}
.sss h2:before{content:"";display:block;width:46px;height:5px;border-radius:3px;background:linear-gradient(90deg,var(--ac),#8a6d2f);margin-bottom:14px}
.sss>div{display:grid;gap:10px}
.sss details{border-radius:3px;border-left:4px solid var(--ac)}
.sss summary{padding:15px 18px;font-size:15px;color:var(--n)}
.sss details p{padding:0 18px 16px;font-size:14px}

/* diğer sektörler */
.oth{padding:40px 0 30px}
.chp.rel{gap:10px}
.chp.rel a{display:inline-flex;align-items:center;gap:9px;background:#fff;color:var(--n);font-weight:700;font-size:14px;border-radius:2px;padding:10px 18px;box-shadow:none;border:1px solid #f3f0e8}
.chp.rel a:hover{box-shadow:none}
.chp.rel a:before{content:"";width:10px;height:10px;border-radius:50%;background:#8a6d2f}
.chp.rel a:nth-child(1):before{background:#8a6d2f}.chp.rel a:nth-child(2):before{background:#8a6d2f}.chp.rel a:nth-child(3):before{background:#8a6d2f}
.chp.rel a:nth-child(4):before{background:#8a6d2f}.chp.rel a:nth-child(5):before{background:#3e6250}.chp.rel a:nth-child(6):before{background:#3e6250}
.chp.rel a:nth-child(7):before{background:#8a6d2f}.chp.rel a:nth-child(8):before{background:#d23b6a}
.chp.rel a:last-child{background:var(--n);color:#fff;border-color:var(--n)}.chp.rel a:last-child:before{display:none}

footer img{height:34px;width:auto}
/* form */
.dkk{padding:48px 0}
.dkk .frm [role=status][style*="rgb(15, 157, 88)"]{color:#3e6250!important}
.dkk .frm .bt:hover{filter:brightness(1.06)}

@media(max-width:1060px){
 .pgh .w{gap:38px}
